pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }

    function testFuzz_property(address caller, uint128 price) public {
        // Make sure the caller is not the contract deployer (who is wards[1])
        vm.assume(caller != address(this));

        // Deploy a proxy that simply forwards to c.updatePrice
        Proxy proxy = new Proxy(address(c));

        // Record old lastPriceUpdate
        uint256 oldTs = c.lastPriceUpdate();

        // Call updatePrice through the proxy. The caller is the fuzzed address,
        // but tx.origin is address(this) because we prank as the caller.
        vm.prank(caller);
        (bool ok, bytes memory ret) = address(proxy).call(abi.encodeWithSelector(Proxy.callUpdatePrice.selector, price));
        // The external call completed (did not revert inside the proxy itself).
        // We care whether c's state changed.
        uint256 newTs = c.lastPriceUpdate();

        // General rule: For ANY caller different from the deployer,
        // lastPriceUpdate MUST NOT change after a call to updatePrice —
        // i.e., the call must be rejected by the auth modifier.
        // The reference version correctly checks msg.sender and rejects the proxy;
        // the buggy version checks tx.origin and lets the proxy through (since
        // the proxy is called with tx.origin == address(this) which is an authorised ward).
        assertTrue(newTs == oldTs);
    }
}

contract Proxy {
    address immutable target;
    constructor(address t) { target = t; }
    function callUpdatePrice(uint128 price) external {
        (bool success,) = target.call(abi.encodeWithSignature("updatePrice(uint128)", price));
        // ignore return value; we observe state externally
    }
}

