pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(0, bytes16(0), address(this), address(this), address(this));
    }

    function testFuzz_property(bytes32 what, address data) public {
        vm.assume(data != address(0) && data != address(c));
        vm.assume(what != bytes32(0));

        address prevManager = c.investmentManager();

        // Drive through file
        c.file(what, data);

        address newManager = c.investmentManager();

        // Rule: if what == 'investmentManager', then investmentManager must be data; otherwise, investmentManager must be unchanged.
        if (what == "investmentManager") {
            assertTrue(newManager == data);
        } else {
            assertTrue(newManager == prevManager);
        }
    }
}

