pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address newManager) public {
        // Ensure caller is not the deployer (who has ward=1)
        vm.assume(caller != address(this));
        // Ensure newManager is not zero
        vm.assume(newManager != address(0));

        // Attempt to change investmentManager as caller
        vm.prank(caller);
        try c.file("investmentManager", newManager) {
            // If the call succeeds, the investmentManager should be changed
            // But only if caller has wards[caller]==1, which they don't
            // So success means the auth modifier was bypassed (bug)
            assertEq(c.investmentManager(), newManager, "Bug: unauthorized caller changed investmentManager");
        } catch {
            // If the call reverted, investmentManager should remain unchanged
            // This is expected for correct version
            assertTrue(c.investmentManager() != newManager, "Auth should prevent unauthorized change");
        }
    }
}

