// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(uint256 fuzzSupply, uint256 fuzzAssets) public {
        // keep fuzzed supply and assets within a reasonable wide range to avoid overflow in reference calculation
        bound(fuzzSupply, 1, 1e36);
        bound(fuzzAssets, 1, 1e36);
        // totalAssets() must equal investmentManager totalAssets view with totalSupply() and pool address
        // Since the constructor sets address(this) for all components, we can call the investmentManager directly
        // to get the expected value. The bug replaces that call with just totalSupply().
        uint256 expected = c.investmentManager().totalAssets(fuzzSupply, address(c));
        // The reference contract would compute based on actual totalSupply(), but we cannot mock it.
        // Instead we rely on the fact that the reference C calls investmentManager.totalAssets(totalSupply(), address(this)).
        // The returned value of totalAssets() should always equal that call result.
        // Because we cannot set totalSupply() directly, we assume the initial state where totalSupply() is 0.
        // The property: totalAssets() must return investmentManager.totalAssets(totalSupply(), address(this)).
        // Under any state, this must hold.
        uint256 realTotalAssets = c.totalAssets();
        uint256 realTotalSupply = c.totalSupply();
        uint256 reference = c.investmentManager().totalAssets(realTotalSupply, address(c));
        assertTrue(realTotalAssets == reference);
    }
}

